function verify_v_html(string $color): string { return '<span class="verify-v admin-dynamic-var" style="--v-color:'.htmlspecialchars($color, ENT_QUOTES).'">V</span>'; }
function admin_verify_remaining(int $seconds): string { $seconds=max(0,$seconds); $d=intdiv($seconds,86400); $seconds%=86400; $h=intdiv($seconds,3600); $seconds%=3600; $m=intdiv($seconds,60); if($d>0)return $d.'天'.$h.'小时'; if($h>0)return $h.'小时'.$m.'分钟'; return max(1,$m).'分钟'; }
