<script>(function(){function fmt(n){n=Math.max(0,n);var d=Math.floor(n/86400);n%=86400;var h=Math.floor(n/3600);n%=3600;var m=Math.floor(n/60);if(d>0)return d+'天'+h+'小时';if(h>0)return h+'小时'+m+'分钟';return Math.max(1,m)+'分钟';}var els=[].slice.call(document.querySelectorAll('[data-cooldown-seconds]'));if(!els.length)return;setInterval(function(){els.forEach(function(el){var s=parseInt(el.dataset.cooldownSeconds||'0',10)-1;el.dataset.cooldownSeconds=String(s);el.textContent=s>0?fmt(s):'已结束';});},1000);})();</script>
